    function start(card,x,y,mouse){if(screen()!=='home'||getComputedStyle(card).display==='none')return;clearTimeout(press?.timer);press={card,x,y,mouse,active:false,timer:setTimeout(()=>{if(!press||press.card!==card)return;press.active=true;arm(card,press.x,press.y)},480)}}
    function move(x,y,e){if(!press)return;if(!press.active){if(Math.hypot(x-press.x,y-press.y)>11){clearTimeout(press.timer);press=null}return}e?.preventDefault?.();update(x,y)}
