    for(const card of cards()){card.addEventListener('touchstart',e=>{if(e.touches.length===1)start(card,e.touches[0].clientX,e.touches[0].clientY,false)},{passive:true});card.addEventListener('mousedown',e=>{if(e.button===0)start(card,e.clientX,e.clientY,true)})}
