  window.openHomeGym=()=>show('gym');

  // An impression means half of a card was visible for 600 ms during this Home visit.
  // A tap has the same visit ID, so the private analysis can compute a true card CTR.
  let homeVisitId='',homeObserver=null;
  const homeImpressionTimers=new Map(),homeImpressed=new Set(),homeImpressedIds=new Set();
  function stopHomeImpressions(){homeObserver?.disconnect();homeObserver=null;for(const timer of homeImpressionTimers.values())clearTimeout(timer);homeImpressionTimers.clear();homeImpressed.clear();homeImpressedIds.clear()}
  function homeCardEvidence(card){return{route:String(card.dataset.route||''),position:[...document.querySelectorAll('.v25HomeCard')].indexOf(card)+1,visitId:homeVisitId,uiVersion:clean(currentUi?.version||'default',80)}}
  function markHomeImpression(card){if(!homeVisitId||homeImpressed.has(card)||screen()!=='home'||document.hidden||getComputedStyle(card).display==='none')return;const id=card.dataset.personalId,key=id?`personal:${id}`:`core:${card.dataset.route}`;if(homeImpressedIds.has(key))return;homeImpressed.add(card);homeImpressedIds.add(key);if(id)log('screen_personal_module_impression',{id,visitId:homeVisitId,mode:privateLiveUi()?.mode||'none'});else log('screen_card_impression',homeCardEvidence(card))}
  function observePersonalModules(){if(homeObserver)document.querySelectorAll('#v25DynamicHome [data-personal-id]').forEach(el=>homeObserver.observe(el))}
  function startHomeImpressions(){stopHomeImpressions();if(screen()!=='home')return;homeVisitId=`home-${now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;if(typeof IntersectionObserver!=='function')return;homeObserver=new IntersectionObserver(entries=>{for(const entry of entries){const card=entry.target,existing=homeImpressionTimers.get(card);if(existing){clearTimeout(existing);homeImpressionTimers.delete(card)}if(entry.isIntersecting&&entry.intersectionRatio>=.5&&!homeImpressed.has(card))homeImpressionTimers.set(card,setTimeout(()=>{homeImpressionTimers.delete(card);if(homeObserver&&screen()==='home'&&card.getBoundingClientRect().top<innerHeight&&card.getBoundingClientRect().bottom>0)markHomeImpression(card)},600))}},{threshold:[0,.5,1]});document.querySelectorAll('.v25HomeCard').forEach(card=>homeObserver.observe(card));observePersonalModules()}
  function logHomeCardOpen(card){markHomeImpression(card);log('ui_press_card',homeCardEvidence(card))}

  let enteredScreenAt=now(),scrollMilestone=0;
  function recordDwell(){const ms=now()-enteredScreenAt;if(ms>=1000&&ms<86400000)log('screen_dwell',{name:screen(),ms});enteredScreenAt=now();scrollMilestone=0}
  function show(name){closeScoreSheet();if(name==='gym')ensureGym();if(typeof currentScreen!=='undefined'&&currentScreen==='tube'&&name!=='tube'&&document.getElementById('reader')?.classList.contains('show')){try{closeReader()}catch(_){}}const target=document.getElementById(name+'Screen');if(!target)return;recordDwell();stopHomeImpressions();document.querySelectorAll('.screen').forEach(x=>x.classList.remove('show'));target.classList.add('show');try{currentScreen=name}catch(_){}window.scrollTo(0,0);if(name==='todos'){renderTodosLean();setTimeout(()=>refreshTasks(),0)}if(name==='calendar'){try{renderCalendar()}catch(_){}log('calendar_open',{})}if(name==='tube'){installTubeContent();try{renderDeck()}catch(_){}forceTube()}if(name==='gym'){renderGym();log('gym_open',{})}renderSlot(name);updateHome();log('screen_enter',{name});if(name==='home')startHomeImpressions()}

  // Keep the daily list small while retaining older HOME Sync imports for selective recovery.
  const TASK_MIGRATION='vbrainTodoMigrationV27',TASK_HIDDEN='vbrainHiddenTaskIdsV27',TASK_OLDER='vbrainOlderTasksV27',TASK_BACKUP='vbrainTodoBackupV27',TASK_SCREENED='vbrainBacklogScreenedV27';
  let hiddenTaskIds=new Set(readState(TASK_HIDDEN,[])),olderTasks=readState(TASK_OLDER,[]);
  if(!Array.isArray(olderTasks))olderTasks=[];for(const t of olderTasks)if(t?.id)hiddenTaskIds.add(String(t.id));
  const sevenDays=7*86400000;
  function rememberOlder(items){const ids=new Set(olderTasks.map(taskId));let changed=false;for(const t of items){const id=taskId(t);if(!id||ids.has(id))continue;olderTasks.push(t);ids.add(id);hiddenTaskIds.add(id);changed=true}if(changed){persistState(TASK_OLDER,olderTasks);persistState(TASK_HIDDEN,[...hiddenTaskIds])}}
  function pruneArchive(){const old=todoState.archive||[],fresh=[],expired=[];let stamped=false;for(const t of old){const raw=t.completedAt,ended=Number(raw)||Date.parse(String(raw||''));if(Number.isFinite(ended)&&ended>0&&now()-ended>=sevenDays){expired.push(taskId(t));continue}if(!Number.isFinite(ended)||ended<=0){t.completedAt=now();stamped=true}fresh.push(t)}if(!expired.length&&!stamped)return;todoState.archive=fresh;expired.forEach(id=>hiddenTaskIds.add(id));if(expired.length)persistState(TASK_HIDDEN,[...hiddenTaskIds]);saveStore('todoState',todoState);if(expired.length)log('todo_archive_expired',{count:expired.length})}
  function migrateTasks(){if(!readState(TASK_MIGRATION,false)){const active=todoState.active||[];if(active.length>40){persistState(TASK_BACKUP,{active,archive:todoState.archive||[],at:now()});const seeds=new Set(seedTodos.map(x=>String(x.id))),keep=active.filter(t=>seeds.has(taskId(t))||taskId(t).startsWith('local-')||t.source==='android');const selected=keep.length?keep:active.slice(0,8);rememberOlder(active.filter(t=>!selected.includes(t)));todoState.active=selected;saveStore('todoState',todoState)}persistState(TASK_MIGRATION,true)}pruneArchive()}
  function restoreOlderTask(id){const i=olderTasks.findIndex(t=>taskId(t)===id);if(i<0)return;const [task]=olderTasks.splice(i,1);hiddenTaskIds.delete(id);persistState(TASK_OLDER,olderTasks);persistState(TASK_HIDDEN,[...hiddenTaskIds]);todoState.active.unshift(enrichTodo(task));taskDirty.add(id);persistTasks('restore_older')}
  function renderOlderTasks(){const host=document.querySelector('#todosScreen>.pad');if(!host)return;let panel=document.getElementById('v25OlderTasks');if(!panel){panel=document.createElement('details');panel.id='v25OlderTasks';panel.className='v25OlderTasks';panel.innerHTML='<summary>Review older synced tasks</summary><input type="search" placeholder="Find an older task…" aria-label="Find an older task"><div class="v25OlderMatches"></div>';host.appendChild(panel);panel.querySelector('input').oninput=()=>renderOlderMatches(panel)}panel.hidden=!olderTasks.length;const summary=panel.querySelector('summary');summary.textContent=`Review older synced tasks (${olderTasks.length})`;if(panel.open)renderOlderMatches(panel)}
  function renderOlderMatches(panel){const q=clean(panel.querySelector('input').value,100).toLowerCase(),box=panel.querySelector('.v25OlderMatches');box.innerHTML='';const matches=olderTasks.filter(t=>!q||String(t.title||'').toLowerCase().includes(q)).slice(0,8);for(const t of matches){const row=document.createElement('div');row.className='v25OlderRow';const label=document.createElement('span'),btn=document.createElement('button');label.textContent=clean(t.title,130);btn.textContent='Restore';btn.type='button';btn.onclick=()=>restoreOlderTask(taskId(t));row.append(label,btn);box.appendChild(row)}if(!matches.length)box.textContent='No matching tasks.'}

  // Tasks are saved on the device first. HOME Sync is a background transport, never a UI gate.
  const taskDirty=new Set();let lastTaskRefresh=0,taskRefreshTimer=0,noteTimer=0;
  const taskId=t=>String(t?.id||t?.notionId||'');
  const taskKey=t=>clean(t?.title||'',160).toLowerCase()+'|'+clean(t?.area||'',80).toLowerCase();
  const googleAvailable=()=>typeof GoogleNative!=='undefined';
  const googleConnected=()=>googleAvailable()&&!!GoogleNative.isConnected?.();
