  function knowledgeModel(){const grouped=new Map();for(const attempt of tubeState.completed||[]){const card=cardMap[attempt.id];if(!card?.topic)continue;const key=clean(card.topic,70).toLowerCase(),g=grouped.get(key)||{topic:card.topic,items:[]};g.items.push(attempt);grouped.set(key,g)}const nodes=[],edges=[];for(const [key,g] of grouped){const unique=new Set(g.items.map(x=>x.id)),valid=g.items.filter(x=>typeof x.quizCorrect==='boolean'),correct=valid.filter(x=>x.quizCorrect).length,id='knowledge:'+key.replace(/[^a-z0-9]+/g,'-');nodes.push({id,label:g.topic,group:'growth',value:valid.length?Math.round(100*correct/valid.length):0,confidence:Math.min(90,unique.size*12+valid.length*3),evidenceCount:g.items.length,description:'A knowledge branch built from completed cards and their specific quiz answers.',reasons:[`${unique.size} ideas completed`,`${correct}/${valid.length} quiz answers correct`],emergent:true});edges.push({a:'learning',b:id,w:Math.min(85,40+g.items.length*5)})}return{nodes,edges}}
  window.VBrainAdaptation={evaluate:evolveLocal,status:()=>readState(LOCAL_ADAPT,{})};
  function privateLiveUi(){
    const patch=parse(readNative('vbrainPrivatePatch'),{}),personal=patch?.liveUi;
    if(!personal||typeof personal!=='object')return null;
    // Accepted improvements stay on the device. An experiment temporarily overrides only
    // the surfaces it names, then the accepted baseline comes back automatically.
    const baseline=personal.baseline&&typeof personal.baseline==='object'?personal.baseline:null;
    const trial=personal.experiment&&typeof personal.experiment==='object'?personal.experiment:(!baseline&&personal.expiresAt?personal:null);
    const expiry=Date.parse(String(trial?.expiresAt||''));
    const experiment=Number.isFinite(expiry)&&expiry>now()&&expiry<=now()+7*86400000?trial:null;
    if(!baseline&&!experiment)return null;
    const safeComponent=c=>{if(!c||typeof c!=='object'||!['card','button'].includes(c.type))return null;const route=String(c.action?.target||'');if(c.action&&(!['home','todos','tube','gym','calendar'].includes(route)||c.action.type!=='route'))return null;const id=clean(c.id,60);if(!id||!clean(c.title,120))return null;return{type:c.type,id,kicker:clean(c.kicker,50),title:clean(c.title,120),text:clean(c.text,240),action:c.action?{type:'route',target:route}:undefined,privateId:id}};
    const limit=(items,n)=>Array.isArray(items)?items.slice(0,n).map(safeComponent).filter(Boolean):[];
    const home=limit(experiment?.home?.components??baseline?.home?.components,2),slots={};
    for(const key of ['calendar','todos','tube','todoDetail','gym'])slots[key]=limit(experiment?.slots?.[key]??baseline?.slots?.[key],1);
    return{home,slots,mode:experiment?'experiment':'baseline',experimentId:experiment?clean(experiment.id,60):'',expiresAt:experiment?expiry:0};
  }
  function syncPrivateUi(){const raw=readNative('vbrainPrivatePatch'),active=privateLiveUi(),sig=`${raw}|${active?.mode||'none'}|${active?.expiresAt||0}`;if(sig===privateUiSignature||privateTarget(document.activeElement))return;privateUiSignature=sig;applyUi(currentUi);log('private_ui_applied',{active:!!active,mode:active?.mode||'none',experimentId:active?.experimentId||'',modules:active?.home.length||0})}
  function applyUi(ui){if(!ui||Number(ui.schema)!==1)return;currentUi=ui;save(UI_CACHE,ui);const personal=privateLiveUi(),accent=ui.theme?.accent;if(/^#[0-9a-f]{6}$/i.test(accent||''))document.documentElement.style.setProperty('--v25-gold',accent);const core=document.querySelector('.v25Core'),dyn=document.getElementById('v25DynamicHome');if(core&&dyn){const replace=ui.home?.mode==='replace';[...core.children].forEach(x=>{if(x!==dyn)x.style.display=replace?'none':''});renderComponents(dyn,[...(ui.home?.components||[]),...(personal?.home||[]),...localModules()],ui.home?.columns||1);observePersonalModules();if(personal?.home.length&&dyn.animate)dyn.animate([{opacity:.45,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'})}for(const name of ['calendar','todos','tube','todoDetail','gym']){const items=[...(ui.slots?.[name]||[]),...(personal?.slots?.[name]||[])];renderComponents(ensureSlot(name),items,1)}}
  async function fetchUi(){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),5000);try{const res=await fetch(`${UI_URL}?t=${Math.floor(now()/1500)}`,{cache:'no-store',signal:controller.signal});if(!res.ok)return;const ui=await res.json(),sig=JSON.stringify(ui);if(Number(ui.schema)!==1||sig===uiSignature)return;if(privateTarget(document.activeElement)){pendingUi=ui;return}uiSignature=sig;applyUi(ui);log('live_ui_applied',{version:clean(ui.version,80)})}catch(_){}finally{clearTimeout(timeout)}}

  let timer=0,ticks=0,liveReady=false;
  function schedule(ms){clearTimeout(timer);timer=setTimeout(tick,ms)}
  async function tick(){if(document.hidden){schedule(2000);return}ticks++;await fetchUi();if(ticks===1||ticks%4===0){try{Native?.checkLiveUpdate?.()}catch(_){}}if(ticks===1||ticks%5===0){refreshTubeFeed();if(maintainTubeDeck()&&screen()==='tube')renderDeck();evolveLocal();try{AdaptiveNative?.checkDeviceCommands?.();AdaptiveNative?.flushPrivateSync?.()}catch(_){}syncBrainContext();syncPrivateUi();refreshTasks()}finalizeDailyScores();if(liveReady&&screen()==='home'&&!brain?.classList.contains('show')&&!privateTarget(document.activeElement)){liveReady=false;try{Native?.applyLiveUpdate?.()}catch(_){}}updateHome();schedule(clamp(currentUi?.pollMs||2000,1500,10000))}
